import { formatCalldata } from "../src/calldata.js";
import * as fs from "fs";

async function run() {
  const descriptorStr = fs.readFileSync(
    "test/erc7730-test-cases/example-safe-multisend.json",
    "utf8",
  );
  const descriptor = JSON.parse(descriptorStr);
  const tx = {
    chainId: 1,
    to: "0x40A2aCCbd92BCA938b02010E17A5b8929b49130D",
    data: "",
  };

  const result = await formatCalldata(tx, descriptor);
  console.log(JSON.stringify(result, null, 2));
}

run().catch(console.error);
